/**
 * Command graph and contested front lines for schematic historical scenes.
 * No inferred unit strengths, affiliations or battle outcomes. Every tactical
 * action is an explicit time-stamped annotation, never generated by animation.
 */
export const COMMAND_ACTIONS=Object.freeze([
 ['hold','Удерживать'],['advance','Наступление'],['withdraw','Отход'],
 ['reform','Перестроение'],['rout','Потеря строя'],['reserve','В резерве']
]);
export const COMMAND_SIDES=Object.freeze([
 ['imperial','Имперские'],['allied','Союзники'],['neutral','Другие']
]);
const actionIds=new Set(COMMAND_ACTIONS.map(([id])=>id));
const sides=new Set(COMMAND_SIDES.map(([id])=>id));
const finite=Number.isFinite;
const idFormat=/^[a-zA-Z0-9][a-zA-Z0-9_-]{1,70}$/;
export function polygonArea(points){
  if(!Array.isArray(points)||points.length<3)return 0;
  let area=0;
  for(let i=0;i<points.length;i++){
    const a=points[i],b=points[(i+1)%points.length];
    area+=a[0]*b[1]-b[0]*a[1];
  }
  return Math.abs(area/2);
}
function crosses(a,b,c,d) {
  const orient=(p,q,r)=>(q[0]-p[0])*(r[1]-p[1])-(q[1]-p[1])*(r[0]-p[0]);
  const ab1=orient(a,b,c),ab2=orient(a,b,d);
  const cd1=orient(c,d,a),cd2=orient(c,d,b);
  if(Math.abs(ab1)<1e-8||Math.abs(ab2)<1e-8||Math.abs(cd1)<1e-8||Math.abs(cd2)<1e-8)return false;
  return (ab1>0)!==(ab2>0)&&(cd1>0)!==(cd2>0);
}
export function validPolygon(points,world){
  if(!Array.isArray(points)||points.length<3||points.length>40)return false;
  if(points.some(p=>!Array.isArray(p)||p.length!==2||!p.every(finite)||
    p[0]<0||p[0]>world.width||p[1]<0||p[1]>world.height))return false;
  if(polygonArea(points)<100)return false;
  const n=points.length;
  for(let i=0;i<n;i++)for(let j=i+1;j<n;j++){
    if(j===i+1||(i===0&&j===n-1))continue;
    if(crosses(points[i],points[(i+1)%n],points[j],points[(j+1)%n]))return false;
  }
  return true;
}
export function polygonCenter(points){
  if(!Array.isArray(points)||!points.length)return [0,0];
  return points.reduce((o,p)=>[o[0]+p[0]/points.length,o[1]+p[1]/points.length],[0,0]);
}
export function commandAt(story,entity){
  return (story.commands||[]).find(c=>c.id===entity?.commandId)||null;
}
export function orderAt(entity,time){
  return (entity?.orders||[]).filter(o=>o.time<=time).sort((a,b)=>b.time-a.time)[0]||null;
}
export function commandRoster(story,time){
  const commands=(story.commands||[]).map(c=>({...c,units:[],count:0}));
  const index=new Map(commands.map(c=>[c.id,c]));
  const visible=(story.entities||[]).filter(e=>(e.from??story.range[0])<=time&&(e.until==null||e.until>=time));
  const byId=new Map(visible.map(e=>[e.id,{...e,children:[],order:orderAt(e,time)}]));
  for(const item of byId.values()){
    const command=index.get(item.commandId);
    if(!command)continue;
    command.count++;
    const parent=byId.get(item.parentId);
    if(parent&&parent.commandId===item.commandId)parent.children.push(item);
    else command.units.push(item);
  }
  return commands.filter(c=>c.count>0).map(c=>({...c,
    units:c.units.sort((a,b)=>a.name.localeCompare(b.name))}));
}
export function validateTactics(story){
  const errors=[];
  if(!story||!story.world||!Array.isArray(story.entities))return ['Отсутствуют данные командования'];
  const commands=story.commands||[];
  if(!Array.isArray(commands)||commands.length>24)return ['Некорректное количество штабов'];
  const sourceIds=new Set((story.sources||[]).map(s=>s.id));
  const commandIds=new Set();
  for(const command of commands){
    if(!command||typeof command.id!=='string'||!idFormat.test(command.id)||commandIds.has(command.id)){
      errors.push('Повторяющийся или неверный ID штаба');continue;
    }
    commandIds.add(command.id);
    if(typeof command.name!=='string'||command.name.trim().length<2)errors.push('Штаб без названия');
    if(!sides.has(command.side))errors.push('Штаб с неизвестной стороной конфликта');
    if(typeof command.commander!=='string')errors.push('Неизвестное поле командира');
    for(const id of command.sources||[])if(!sourceIds.has(id))errors.push('Нет источника штаба: '+id);
  }
  const entityMap=new Map(story.entities.map(x=>[x.id,x]));
  for(const entity of story.entities){
    if(entity.commandId&&!commandIds.has(entity.commandId))errors.push('Объект привязан к несуществующему штабу: '+entity.name);
    if(entity.parentId){
      const parent=entityMap.get(entity.parentId);
      if(!parent||parent.id===entity.id)errors.push('Неверный родитель подразделения: '+entity.name);
      else if(parent.commandId!==entity.commandId)errors.push('Подразделения одной цепочки должны относиться к одному штабу');
    }
    const visited=new Set([entity.id]);let cursor=entity;
    for(let i=0;i<story.entities.length+1;i++){
      const parent=cursor.parentId&&entityMap.get(cursor.parentId);
      if(!parent)break;
      if(visited.has(parent.id)){errors.push('Цикл командования: '+entity.name);break;}
      visited.add(parent.id);cursor=parent;
    }
    const orders=entity.orders||[];
    if(!Array.isArray(orders)||orders.length>32){errors.push('Слишком много приказов: '+entity.name);continue;}
    const times=new Set();
    for(const order of orders){
      if(!order||!finite(order.time)||order.time<story.range[0]||order.time>story.range[1]||
         order.time===0||times.has(order.time))errors.push('Неверная дата приказа: '+entity.name);
      times.add(order?.time);
      if(!actionIds.has(order.action))errors.push('Неизвестный приказ: '+entity.name);
      if(!['confirmed','estimated','disputed','hypothetical'].includes(order.confidence))
        errors.push('Не указана уверенность приказа: '+entity.name);
      if(order.confidence==='confirmed'&&(!order.sources||!order.sources.length))
        errors.push('Подтверждённый приказ требует источник: '+entity.name);
      for(const id of order.sources||[])if(!sourceIds.has(id))errors.push('Источник приказа не существует: '+entity.name);
    }
  }
  for(const feature of story.features||[]){
    if(feature.kind!=='boundary')continue;
    if(!validPolygon(feature.points,story.world))errors.push('Неверная многоугольная граница: '+feature.label);
  }
  return [...new Set(errors)];
}
